					// here still uses the original dimension 'i', so we can
					// apply the stencil exactly as in the original code.
					tile_trav.for_each([=](auto state) {
						auto left  = state - noarr::idx<'i'>(1);
						auto right = state + noarr::idx<'i'>(1);

