// initialization function
// -----------------------------------------------------------------------------
//
// Optimizations vs. original:
// - Compute n and its reciprocal once outside the traversal.
// - Use multiplication by inv_n instead of division inside the loop.
// - Capture A, B by reference to avoid copying bags into the lambda.
// -----------------------------------------------------------------------------
void init_array(auto A, auto B) {
	using namespace noarr;

	const std::size_t n_idx = A | get_length<'i'>();
	const num_t n = static_cast<num_t>(n_idx);
	const num_t inv_n = num_t(1) / n;

	traverser(A, B).for_each([&](auto state) {
		const num_t i = static_cast<num_t>(get_index<'i'>(state));

		A[state] = (i + num_t(2)) * inv_n;
		B[state] = (i + num_t(3)) * inv_n;
	});
}

