// computation kernel
// -----------------------------------------------------------------------------
//
// Semantic summary (unchanged):
//   For each time step:
//     - First sweep:  B[i] = w * (A[i-1] + A[i] + A[i+1]) for i in 1..n-2
//     - Second sweep: A[i] = w * (B[i-1] + B[i] + B[i+1]) for i in 1..n-2
//   Boundary points i = 0 and i = n-1 are never updated.
//
// Optimizations applied:
//   1) Precompute constant weight w once.
//   2) Use a proto-structure that:
//        - slices the interior i-range to [1, n-2]
//        - tiles that interior via into_blocks_dynamic<'i','I','i','g'>
//        - hoists the tile index 'I' to the top level
//      This changes only traversal order (improves spatial locality for large n)
//      and does *not* change which elements are updated.
//   3) Within each sweep, use a simple sliding window along i to reduce neighbor
//      loads: after the first interior point of a contiguous run, each next
//      point only loads the new rightmost neighbor. At tile boundaries (where
//      i is no longer consecutive), we re-initialize the window, so correctness
//      is preserved.
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	const std::size_t n = A | get_length<'i'>();

	// No interior points to update
	if (n <= 2 || tsteps <= 0)
		return;

	// Stencil weight, hoisted once
	constexpr num_t w = static_cast<num_t>(0.33333);

	// View selecting interior points i in [1, n-2]
	// (length = n-2, indices 1..n-2 in the original structure)
	auto interior_base = noarr::slice<'i'>(1, n - 2);

	// Tile size for i (chosen to give a reasonable working-set size).
	// It is a compile-time constant so the tiling meta-structure can be
	// specialized and optimized by the compiler.
	constexpr std::size_t tile_i = 1024;

	// Tiled interior view:
	//   - slice<'i'>(1, n-2)       : restrict to interior points
	//   - into_blocks_dynamic      : split interior into blocks of tile_i
	//   - hoist<'I'>               : make tile index 'I' the outermost dim
	//
	// This is used *only* for traversal order. Via traverser(...).order(...),
	// the state we see in the lambdas still contains just 'i' (original index),
	// while the iteration proceeds block-by-block in 'I' and then within-block.
	auto interior_tiled =
		interior_base ^
		noarr::into_blocks_dynamic<'i', 'I', 'i', 'g'>(noarr::lit<tile_i>) ^
		noarr::hoist<'I'>();

	// Structure used only to iterate over time steps; 't' is not a dimension
	// of A/B, so this does not affect their layout.
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	#pragma scop
	traverser(time_struct).for_each([&](auto /*t_state*/) {
		// ---------------------------------------------------------------------
		// First sweep: update B from A on interior points.
		// Sliding window over A[i-1], A[i], A[i+1] along i:
		//   - For the first interior i of a contiguous run:
		//       left  = A[i-1], center = A[i], right = A[i+1]
		//   - For the next i' = i+1 in the same run:
		//       left  <- center
		//       center <- right
		//       right <- A[i'+1]
		//   - At tile boundaries or any non-consecutive i, we reinitialize
		//     from A to preserve correctness.
		// ---------------------------------------------------------------------
		{
			bool first_in_run = true;
			std::size_t prev_i = 0;
			num_t left = num_t(0), center = num_t(0), right = num_t(0);

			traverser(B, A).order(interior_tiled).for_each([&](auto state) {
				const std::size_t i = get_index<'i'>(state);

				if (first_in_run || i != prev_i + 1) {
					// Either the first interior point overall or we jumped
					// (e.g., moved to a new spatial tile). Initialize window.
					left   = A[state - noarr::idx<'i'>(1)];
					center = A[state];
					right  = A[state + noarr::idx<'i'>(1)];
					first_in_run = false;
				} else {
					// Slide the window forward by 1 element.
					left   = center;
					center = right;
					right  = A[state + noarr::idx<'i'>(1)];
				}

				prev_i = i;
				B[state] = w * (left + center + right);
			});
		}

		// ---------------------------------------------------------------------
		// Second sweep: update A from B on the same interior.
		// Identical sliding-window scheme, but reading from B and writing A.
		// ---------------------------------------------------------------------
		{
			bool first_in_run = true;
			std::size_t prev_i = 0;
			num_t left = num_t(0), center = num_t(0), right = num_t(0);

			traverser(A, B).order(interior_tiled).for_each([&](auto state) {
				const std::size_t i = get_index<'i'>(state);

				if (first_in_run || i != prev_i + 1) {
					left   = B[state - noarr::idx<'i'>(1)];
					center = B[state];
					right  = B[state + noarr::idx<'i'>(1)];
					first_in_run = false;
				} else {
					left   = center;
					center = right;
					right  = B[state + noarr::idx<'i'>(1)];
				}

				prev_i = i;
				A[state] = w * (left + center + right);
			});
		}
	});
	#pragma endscop
