		const auto i = get_index<'i'>(state);
		const num_t x = static_cast<num_t>(i);

		// A[i] = (i + 2) / n
		A[state] = (x + num_t(2)) * inv_n;
		// B[i] = (i + 3) / n
		B[state] = (x + num_t(3)) * inv_n;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// Spatial problem size
	const auto n = A | get_length<'i'>();

	// Nothing to do for degenerate domains or no time steps
	if (n < 3 || tsteps <= 0)
		return;

	// Jacobi stencil weight (matches original constant 0.33333)
	constexpr num_t w = static_cast<num_t>(0.33333);

	// Structure used only to iterate over time steps: dimension 't'
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(tsteps);

	// View selecting the interior points i in [1, n-2]
	// (boundary points i = 0 and i = n-1 remain fixed)
	auto interior = noarr::slice<'i'>(1, n - 2);

	// --------------------------------------------------------------------
	// Spatial blocking over 'i' for better cache locality
	//
	// We split the interior [1, n-2] into tiles of at most TILE_I elements.
	// into_blocks_dynamic<'i','I','i','p'> introduces:
	//   - 'I' : tile index (major dimension)
	//   - 'i' : intra-tile index (still the original spatial coordinate)
	//   - 'p' : presence dimension (length 0 or 1) for elements in the
	//           last, possibly partial tile; traverser will not generate
	//           any states where 'p' is empty.
	//
	// hoist<'I'> makes the tile index the outermost loop for traversal.
	//
	// Note: thanks to traverser(order(...)), the states seen in the
	//       lambdas still contain only the original 'i' dimension, so
	//       neighbor access using i±1 via state ± idx<'i'>(1) remains
	//       correct and simple.
	// --------------------------------------------------------------------
	constexpr std::size_t TILE_I = 512; // tuned for L1/L2; safe for any N

	auto blocked_interior =
		interior
		^ noarr::into_blocks_dynamic<'i', 'I', 'i', 'p'>(TILE_I)
		^ noarr::hoist<'I'>();

	#pragma scop
	traverser(time_struct).for_each([=](auto /*t_state*/) {
		// ----------------------------------------------------------------
		// First sweep: update B from A on interior points.
		// We traverse tiles in 'I', and within each tile we traverse
		// the interior indices 'i'. Due to the blocking, the working
		// set A[i-1..i+1] / B[i] of a tile stays in cache across the
		// sweep for that tile.
		// ----------------------------------------------------------------
		traverser(B, A)
			.order(blocked_interior)
			.template for_dims<'I'>([=](auto tile_trav) {
				// tile_trav has tile index 'I' fixed; for_each iterates
				// over the remaining dimensions ('i' and 'p')
				tile_trav.for_each([=](auto state) {
					// state only has the original spatial index 'i'
					auto left  = state - noarr::idx<'i'>(1);
					auto right = state + noarr::idx<'i'>(1);

					B[state] = w * (A[left] + A[state] + A[right]);
				});
			});

		// ----------------------------------------------------------------
		// Second sweep: update A from B on the same interior.
		// The tiling/order is identical; we only swap the roles of A/B.
		// ----------------------------------------------------------------
		traverser(A, B)
			.order(blocked_interior)
			.template for_dims<'I'>([=](auto tile_trav) {
				tile_trav.for_each([=](auto state) {
					auto left  = state - noarr::idx<'i'>(1);
					auto right = state + noarr::idx<'i'>(1);

					A[state] = w * (B[left] + B[state] + B[right]);
				});
			});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size and number of time steps
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set the length of the spatial dimension
	auto set_lengths = noarr::set_length<'i'>(n);

	// allocate bags for A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_jacobi_1d(static_cast<int>(tsteps), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to inhibit dead-code elimination in benchmarks)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
